  ('4343SADRL', 'Students study recent deep reinforcement learning papers, replicate results in small groups, present progress and write a research-style report.'),
  ('4343SMTAI', 'Students investigate trustworthy AI topics such as robustness, verification, explainability, bias and privacy through recent research papers, presentations and group reports.'),
  ('4343SNACS', 'Students study network science for social and technical systems, covering network models, algorithms, visualization, epidemics, pattern detection and computational complexity.'),
  ('4343SPDSX', 'Students learn how data science supports sports analysis, covering training optimization, injury prevention, tactical decisions, time series, feature construction and subgroup discovery.'),
  ('4343SWVRX', 'Students study formal verification, especially model checking, to prove correctness of software and hardware systems beyond what testing alone can guarantee.'),
  ('4343SYSSS', 'Students study software and hardware security, covering vulnerabilities, mitigations, secure development, processor-level attacks, roots of trust and research-oriented group projects.'),
  ('4343TXTMX', 'Students learn text mining foundations and applications, including text representation, classification, annotation, transformer models, information extraction, topic modeling, summarization and sentiment analysis.'),
  ('4343URBC6', 'Students study urban computing with spatio-temporal data mining, learning how computing methods address mobility, traffic, pollution and environmental challenges.'),
  ('4373MUMAB', 'Students use mathematical and computational models to study biological systems across scales, connecting biological questions with applied mathematical problem-solving.'),
  ('4383ARCR3', 'Students explore emotional, creative, curious and lifelike robots, then build an artificial creature that makes a chosen human-like quality tangible.'),
  ('4383COMCR', 'Students explore computational models of creativity, creative agents, co-creative systems, evaluation methods and philosophical questions through literature discussions and a practical project.'),
  ('4383HICNM', 'Students compare human cognition with intelligence in nature and machines, reflecting on recent AI advances and what they imply for understanding minds.'),
  ('4383VGFR6', 'Students learn to design and conduct research with video games or interactive experiences, combining game studies, development practice and applied research design.'),
  ('4433COMST', 'This course introduces computational statistics through numerical methods, algorithms, simulation and mathematical techniques for solving statistical problems in practice.'),
  ('4433DATVI', 'Students learn how to design effective statistical visualizations, evaluate graphical choices and communicate data patterns clearly across applied research contexts.'),
  ('4433EXPDA', 'Students learn exploratory data analysis methods for high-dimensional datasets, using visualization and statistical techniques to uncover relationships beyond simple two-variable plots.'),
  ('4433HDDAN', 'Students analyze high-dimensional biological and biomedical data, learning statistical methods for many variables, small sample sizes and complex dependency structures.'),
  ('4433LGMO6', 'Students study linear regression, analysis of variance and generalized linear models for explaining how predictors influence quantitative or categorical response variables.'),
  ('4433STATG', 'Students model genetic data for life science applications, studying pedigrees, linkage, heritability, association studies, Mendelian randomization and gene expression analysis.'),
  ('4433STATL', 'Students learn supervised and unsupervised statistical learning methods, including regression, classifiers, clustering, dimension reduction, model selection and evaluation.'),
  ('4609COMNWY', 'Students study complex networks across physics, mathematics and computer science, covering real-world network properties, models, algorithms, visualization, epidemics and computational complexity.')
)
update public.courses c
set description = s.description
from summaries s
where c.code = s.code;
